from html import escape
lessons=[]
def add(title,goal,body,questions,hint1,hint2,task,prereq='数组、循环、函数；不预设学过链表'):
    lessons.append(dict(title=title,goal=goal,body=body,questions=questions.split('|'),hints=[hint1,hint2],task=task,prereq=prereq))
def box(t,s):return f'<aside class="callout"><strong>{t}</strong><p>{s}</p></aside>'
def table(head,rows):return '<div class="table-scroll"><table><thead><tr>'+''.join(f'<th>{x}</th>' for x in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(f'<td>{x}</td>' for x in r)+'</tr>' for r in rows)+'</tbody></table></div>'
def code(s):return '<pre><code>'+escape(s)+'</code></pre>'
def chain(s):return '<div class="chain-picture" role="img" aria-label="'+escape(s,quote=True)+'">'+escape(s)+'</div>'
def coach(s):return '<details class="coach"><summary>教练备课 / 尝试后核对</summary><p>'+s+'</p></details>'
add('一条队伍，不一定挤在一起','从卡片与箭头理解“后一个是谁”。',
'''<p class="lead">把队伍记下来，可以记座位，也可以记伙伴。</p><p>三位同学按小鹿、小熊、小兔排队。用数组表示时，我们常把第 1、2、3 个位置依次存好。另一种办法：每个人拿张纸条，写“我后面是谁”；再用一张入口卡记“第一个是谁”。桌上卡片怎样摆都可以，队伍的顺序由纸条决定。</p>'''+chain('入口 → 小鹿 → 小熊 → 小兔 → 结束')+'''<p>这样的卡片叫<strong>结点</strong>。结点至少要存两件事：自己的数据、下一个结点的位置线索。线索叫<strong>链接</strong>；图上画成箭头。最后一个没有后继，需要专门的结束标记。</p><p>让小猫站到小鹿后面时，目标是让箭头表达新队伍。小兔的卡片无需搬家。今天只动卡片，不写 C++，也不需要认识内存地址。</p>''',
'把卡片散放，沿入口还能读出原队伍吗？|让小猫插到小鹿后面，谁的“后面是谁”会改变？|如果只把小猫放在小鹿旁边、纸条不改，计算机知道队伍变了吗？',
'计算机只沿纸条走，不看桌上卡片的距离。','画出插入前后所有箭头，圈出发生变化的起点。',
'用 4 张纸演一次插队，再演一次离队。请家长只按箭头读队伍，检查和你设想的一不一样。')
add('编号、位置、数值：三个不同的名字','把结点身份与当前排名分开。',
'''<p class="lead">搬到队首，不会让你的身份证号码变成 1。</p><p>给结点分配固定编号：4 号存值 8，1 号存值 5，7 号也存值 8。入口指向 4，链接为 4→1→7。4 号是队伍中的第 1 个；它的编号是 4，值是 8。这三个数承担不同职责。</p>'''+table(['固定编号 id','数据 value','当前第几个'],[['4','8','1'],['1','5','2'],['7','8','3']])+'''<p>把 7 号移到最前面后，它仍是 7 号，值仍为 8；只有排名变了。两位同学可以同名，两个结点也可以同值，所以“删除值为 8 的结点”还需要说明删第一个还是全部。</p><p>之后的数组模拟，用编号当数组下标。<code>nxt[4]=1</code> 表示 4 号的后继是 1 号，绝不表示 4 号后面还有 1 个人。数组编号可以跳跃，不能用 <code>id++</code> 代替沿链接走。</p>''',
'队伍变成 7→4→1 后，第 1 个结点的编号和值分别是什么？|为什么知道值为 8，还不能唯一确定结点？|从 4 号走到下一位，应该看 nxt[4] 还是编号 5？',
'给卡片分别写上“身份证、名字、排第几”。','只有排名会随着插队变化；编号用于稳定地找到同一张卡片。',
'自己造两个同值结点，把队伍重排两次；每次列出编号、值、排名，证明它们不能混用。')
add('变量登记表：谁保管入口，谁负责走路','把程序变量翻译成队伍中的角色。',
'''<p class="lead">带路的人向前走，入口牌不能跟着丢。</p><p>把入口记作 <code>head</code>，用 <code>cur</code> 表示现在正在看的结点，<code>nxt[id]</code> 存后继编号。为了避免与真实结点混淆，前半讲统一保留编号 0 表示“没有结点”，真实结点从 1 开始。</p>'''+table(['角色','初值','什么时候变'],[['head：第一个结点','空表为 0','首结点改变'],['cur：当前访问位置','head','访问完向后走'],['nxt[id]：id 的后继','按队伍连接','插入、删除或改序'],['value[id]：结点数据','读入的数据','题目要求改值时'],['used：已分配最大编号','0','分配新结点时加 1'],['size：活跃结点数量','0','实际插入加 1，实际删除减 1']])+'''<p>后面若不需要快速报告数量，可以不存 size。每增加一个变量，就增加一项需要维护的承诺。used 与 size 也不一样：删除通常不会让已分配编号倒退。</p>'''+box('本讲的记号约定','nxt、pre 是数组字段；next、prev 是指针结点字段。例子切换表示时会说明。0 是数组模拟的空编号，不是一张可以输出的数据卡。'),
'遍历时若不断改变 head，走到末尾后入口还在吗？|已分配 5 个结点、删除其中 2 个，used 与 size 一定相等吗？|空表为什么不能先读取 value[cur] 再判断 cur？',
'让一张纸一直贴在入口，另一张纸扮演走路的人。','入口描述整条链，游标描述这一次操作走到了哪；两个角色别合并。',
'用自己的话重写这张登记表。选一个不必存在的变量，说明何时可以省掉它。')
add('用数组造出第一条链','理解数组模拟链表的存储与连接。',
'''<p class="lead">房间连续编号，队伍仍可以拐着走。</p><p>开两个等长数组 value 和 nxt。同一个下标合起来表示一个结点；先给数据，再建立链接。例子用 1、2、3 三个槽位，但队伍为 2→3→1。</p>'''+table(['编号','value','nxt'],[['1','30','0'],['2','10','3'],['3','20','1']])+chain('head=2 → [2号:10] → [3号:20] → [1号:30] → 0')+'''<p>这常叫<strong>数组模拟链表 / 静态链表</strong>。存储仍是数组，逻辑顺序却由 nxt 决定。这里“静态”描述存储方法，和 C++ 的 <code>static</code> 关键字不是一回事。</p><p>真实操作里常按分配顺序使用新编号：每次取一个从未使用的槽位。若最多有 n 个初始结点和 q 次新建，可以预留至少 n+q 个真实槽位，另留空编号或哨兵。声明长度为 CAP 的数组合法下标是 0～CAP−1；分配前要检查容量。</p>'''+code('value[id] = 新数据;\nnxt[id] = 后继编号;  // 两个字段属于同一个结点'),
'按下标 1、2、3 输出，和按箭头输出一样吗？|删除 2 号后，把 3 号数据搬到 2 号会影响哪些已有链接？|累计新建 100 次但现在只剩 2 个，能只开 3 个槽位吗？',
'分开问“现在在链上的有多少”和“历史上领过多少编号”。','本讲基础版本不回收编号；需要按累计分配量预留空间。',
'画出三个槽位与入口。改变两条链接，保持每个槽位数据不动，读出另一种队伍顺序。')
add('遍历与查找：顺着线走到哪里停','建立先判断、再访问、再前进的循环。',
'''<p class="lead">找不到也是一种正常结果。</p><p>遍历要按顺序访问每个活跃结点。先令 cur 指向 head；只要 cur 不是 0，就访问它，再沿 nxt 前进。查找则多一个停止原因：当前值已满足要求。</p>'''+code('cur = head;\nwhile (cur != 0) {\n    // 访问当前结点\n    cur = ______;  // 沿哪一条箭头走？\n}')+'''<p>“查找第一个值为 x 的结点”，返回结点编号；找到末尾仍未命中，返回空编号 0。空表从一开始就不能进入访问。若改成查找第 k 个结点，需要增加“已经走过几个”的角色，不能把 k 当成编号直接使用。</p><p>不带环的链中，每次前进一步，最多访问 n 个结点。因此遍历与最坏情况查找都为 O(n)，不是因为结点能按编号访问就变成 O(1)。</p><div class="lab" id="walk-lab"></div>''',
'从 2→3→1 这条链查找值 30，应按什么编号顺序走？|若 cur 一直不变，会出现哪种运行现象？|值不存在与链为空时，查找分别在哪里停？',
'只盯一个游标；每轮结束时写下它下一次指向谁。','循环必须让游标靠近停止状态；先判断空编号，再读取对应数据。',
'写出遍历与“找第一个值”的两个小函数。测空表、单结点命中、最后才命中与不存在；说清返回的是编号还是值。')
add('创建：头插、尾插与空表','知道每次新建后，入口与尾巴怎样变化。',
'''<p class="lead">一张张放到最前面，读出来会反过来。</p><p>依次读入 10、20、30。每次把新结点接到队首叫头插：先让新结点连向原来的 head，再更新 head。尾插则把新结点接在末尾，通常维护 tail，避免每次都从头找尾巴。</p><p>对空表做第一次尾插是特别的一步：还没有旧尾巴，不能让不存在的 tail 指向新人；需要同时建立 head 与 tail。以后每次尾插，新结点后继为 0，旧尾巴指向新人，最后移动 tail。</p>'''+table(['要维护的承诺','创建过程中的检查'],[['head 指向第一个活跃结点','空表 head=0'],['tail 指向最后一个活跃结点','非空时 nxt[tail]=0'],['输入顺序按要求保留','先用三张不同值卡片验证']])+'''<p>维护 tail 的尾插总共 O(n)。若每次尾插都遍历旧链找尾，工作量为 0+1+…+(n−1)，总共 O(n²)。同样叫“创建”，实现方式不同，代价就不同。</p>''',
'10、20、30 依次头插，入口最后指向哪张？|空表第一次尾插，head 与 tail 分别该代表谁？|不保存 tail，每次找尾巴会重复经过哪些旧结点？',
'先只推第一个和第二个结点，别一口气写完整循环。','空表没有旧尾巴；头插改变入口，尾插改变末端。',
'分别手推头插和尾插的空表→1 个→3 个过程，再独立实现。记录每步 head、tail 与新链接。')
add('单链表插入：先保存旧去向','用最小反例发现覆盖链接的后果。',
'''<p class="lead">先记住桥那头是谁，再改桥。</p><p>已知活跃结点 p，要把新结点 u 放在 p 后面。设 p 原后继为 q。插完应当是 p→u→q；其他结点关系不变。u 必须是尚未在这条链上的结点，否则可能造成环或断链。</p>'''+chain('改前：p → q       新结点：u\n目标：p → u → q')+'''<p>问题不在于有几行代码，而在于第一行是否毁掉第二行需要的旧信息。实验允许你选写入次序，观察每一步；先预测哪里会出现回环，再按按钮。</p><div class="lab" id="insert-lab"></div>'''+coach('局部核对：可以先 nxt[u]=nxt[p]，再 nxt[p]=u；也可先把旧后继存入 q，再按正确关系赋值。若直接先 nxt[p]=u，再 nxt[u]=nxt[p]，第二句读到的是新值 u，形成 u→u，并使原后缀从入口不可达。注意“先改 p”在已保存 q 时不一定错，根因是读错了新旧状态。')+'''<p>若要在首结点之前插入，可以单独做头插；也可以下一站引入一个不存业务数据的入口哨兵。只知道 p 后插时，改链接是 O(1)，但若 p 需要查找，还要另算查找成本。</p>''',
'只有 p→q 两个结点时，若先把 p 的箭头改成 u，旧 q 还能从 p 找到吗？|再把“p 现在的后继”写入 u，会指向谁？|你准备怎样保住旧后继，让第二步还能使用它？',
'在每一次赋值之后重新画图；第二行读的是变化后的图。','可以调整写入顺序，也可以先增加一个保存旧去向的变量。',
'自己写插入局部代码；用尾部插入与中间插入验证。遮住提示，说明两行的先后依据。')
add('单链表删除：谁能跨过目标','区分“知道目标”与“知道前驱”。',
'''<p class="lead">让一张卡片离队，要改它前面那张纸条。</p><p>单链表 p→u→q，要删除 u，主动作是让 p 越过 u 连到 q。把 u 的值设成 0 或把 nxt[u] 清空，都不会自动让 p 跨过它。我们要改的是可达关系。</p><p>为什么常说“单链表删除需要前驱”？因为 u 只记录后面是谁，没有直接告诉你 p 在哪里。若只有 u 编号，通常要从入口找前驱；已知 p 才能 O(1) 删除它的后继。不能用“复制后继数据”的特殊技巧代替一般删除，它不适用于尾结点，也会改变身份语义。</p>'''+box('入口哨兵：让首结点也有前驱','从本例开始，可以让编号 0 作为固定入口哨兵 H；nxt[H] 存首结点，链尾仍用 0 表示终止。只从 nxt[H] 开始遍历，遇到 0 停，不把 H 当数据访问。head=0 的“无哨兵”约定与 H=0 的“有哨兵”约定要选定一种，不能混用。')+'''<p>有哨兵后，删除首结点也能用“改前驱的后继”处理。若额外维护 tail，删除尾结点后 tail 应成为 p；删空后 tail 可约定为 H。数组槽位暂时不回收，删除与释放内存是两件事。</p>''',
'在 H→A→B→0 中删除 A，哪个箭头必须改变？|只知道 B 的编号，能从 B 直接找到 A 吗？|若只清空 nxt[A]，从 H 出发会看到什么？',
'让游标扮演“站在门口准备跨过下一位的人”。','要改的是进入被删结点的箭头；因此先确认谁保管这条箭头。',
'实现“删除已知前驱的后继”，并规定没有后继时怎样处理。测试删除首、尾、唯一结点与空表操作。')
add('边走边删：不要跨过还没检查的人','处理连续删除与遍历变量的更新。',
'''<p class="lead">后面的同学补到眼前，你还没有检查过她。</p><p>任务是删除所有值为 x 的结点。使用哨兵 H，p 始终站在“已经处理部分的最后一位”，检查的是 p 的后继 u。若保留 u，已处理部分延长，p 可以前进；若删掉 u，新后继还没检查，p 应留在原地。</p>'''+chain('H → [5] → [5] → [7] → 0')+'''<p>这个例子专门检查“连续两个目标值”。只试 [5,7] 可能掩盖错误：如果删除后仍把 p 向前移动，第二个 5 就可能被跳过。不要先改符号，先说清 p 的角色在两个分支里是否仍成立。</p>'''+code('p = H;\nwhile (nxt[p] != 0) {\n    u = nxt[p];\n    if (value[u] == x) {\n        // 删除 u；p 是否移动？\n    } else {\n        // 保留 u；p 是否移动？\n    }\n}')+'''<p>正确遍历每个原结点只检查一次，总 O(n)。即使 p 没移动，删除分支也让未处理结点减少，所以不会原地耗着；终止性不只来自“游标数值变大”。</p>''',
'删掉第一个 5 后，p 的后继是谁，检查过了吗？|两个分支都让 p 前进，会跳过哪一位？|删除分支不动 p 时，什么量仍在减少？',
'把“已检查”和“未检查”画成两段，p 始终守住分界。','删除后未检查段变短；保留后 p 向前一步，两种动作都在推进任务。',
'补完自己的局部循环，测 [5,5,7]、全是 5、没有 5、空表。每轮记录 p 和 nxt[p]。')
add('从编号走向 C++ 指针','把地址、字段与结点生命周期连接起来。',
'''<p class="lead">编号是找卡片的线索，地址也是。</p><p>数组模拟用整数编号找结点。指针链表把“去哪里找”的线索换成内存地址，类型 <code>Node*</code> 表示能指向 Node 的指针；<code>nullptr</code> 表示不指向结点。它与真实结点的数据 0 没有关系。</p>'''+code('struct Node {\n    int value;\n    Node* next;\n};\n// 认识字段即可；不是完整解题程序。\nNode* u = new Node{7, nullptr};')+'''<p><code>p-&gt;value</code> 读取 p 指向结点的数据，等价于 <code>(*p).value</code>；使用前必须保证 p 指向仍存活的结点。<code>Node* q=p;</code> 只是复制地址，两根指针可能指向同一结点，没有新建一张卡片。</p><p>删除时，要先保存后继、让前驱绕过目标，再对独占管理的堆结点 <code>delete</code>。delete 后不能再用该地址读 next；其他指向它的别名也失效。把一个指针设为 nullptr 不会自动修好其他别名。离开函数后，局部普通变量的地址也不能继续当有效结点使用。</p>'''+coach('给孩子只讲当前用到的一项生命周期规则。手写 new/delete 适合理解五级代码阅读；竞赛实现可优先使用预留容量的数组模拟。若用 vector 存结点，扩容可能使之前保存的元素指针失效，编号引用则仍可重新索引。'),
'p 与 q 存同一地址，修改 q 指向结点的值后，p 看到什么？|delete u 后才读取 u->next，为什么已经晚了？|存值 0 的结点与 nullptr 是同一种情况吗？',
'画两根线指向同一张卡；剪掉卡片后，两根线都没有有效目标。','线索与对象分开看：复制线索没有复制对象；释放对象也不等于更新所有线索。',
'把第 7 站的编号图翻译成指针图，只写局部插入 / 删除片段。再把空指针与已释放指针两种错误用自己的话区分。')
add('双链表：左右都留一条路','创建双链并建立双向一致性。',
'''<p class="lead">能回头找人，需要额外保存来路。</p><p>单链结点只知道后继。双链再存一个前驱 <code>pre[id]</code>。对相邻活跃结点 a、b，必须同时满足 nxt[a]=b 与 pre[b]=a。只改一边，正着走与倒着走会讲出两种队伍。</p><p>本讲双链数组统一用两个哨兵：H=0，T=1；真实结点从 2 开始。空链也保留 H↔T，即 nxt[H]=T、pre[T]=H。只要求 H 的右链接与 T 的左链接有意义，不读取 H 的前驱或 T 的后继。</p>'''+chain('H ⇄ A ⇄ B ⇄ T')+'''<p>创建时从空链开始，把每个新结点插在 T 前面。最后一个活跃结点可以由 pre[T] 直接找到，因此无需再存 tail。这里没有“0 是线性链的结束编号”的旧规则：向右走遇 T 停，向左走遇 H 停。</p>'''+table(['不变式','含义'],[['pre[nxt[x]]=x','x 的右邻居认 x 为左邻居；x≠T'],['nxt[pre[x]]=x','x 的左邻居认 x 为右邻居；x≠H'],['H、T 不承载业务数据','只做边界，不输出、不删除']]),
'只有一个真实结点 A 时，要画出哪四个方向的箭头？|空链从 H 往右第一步是谁？|若只更新 nxt 而不更新 pre，怎样走能最早发现问题？',
'从 H 正着读，再从 T 反着读，比较两份顺序。','两份记录应恰好互为逆序；每对相邻关系都要双方承认。',
'从 H↔T 建出三个结点。写完整的 pre/nxt 表，并检查每条相邻关系的逆向对应。')
add('双链增删：先圈出四条边','把局部变化变成一份写入清单。',
'''<p class="lead">先画修改后的图，再决定写哪几个格子。</p><p>在 p 与 q 之间插入 u，修改后应为 p↔u↔q。先把旧 q 保存好，再让 u 的两个方向指向 p 和 q，最后让两位旧邻居认识 u。一个操作完成后，整个链应恢复双向一致；不要在半更新时开始别的遍历。</p><p>删除活跃结点 u 时，先记 p=pre[u]、q=nxt[u]，再把 p 和 q 互接。u 自己的字段可以保留，供之后的撤销记录使用；但它已不属于活跃队伍，不能继续按活跃结点使用。</p><div class="lab" id="double-lab"></div>'''+coach('插入关系核对：pre[u]=p、nxt[u]=q、nxt[p]=u、pre[q]=u。删除关系核对：nxt[p]=q、pre[q]=p。数组实验另有 alive 标记，防止重复删除。已知活跃 u 时，这些局部写入是 O(1)；不是说按值定位 u 也免费。')+'''<p>哨兵让首尾操作沿用同一张关系图：p 可以是 H，q 可以是 T。但 u 不可以是哨兵，也不能重复加入已在链内的结点。</p>''',
'插入 u 后，p 和 q 各需要知道哪一个新邻居？|删除 u 后，反向从 q 走应当到谁？|重复删除同一个 u，保存的旧邻居还一定相邻吗？',
'先只检查目标 u 左右的局部图，不动更远处。','相邻结点互相承认才完成；“删除过”与“仍活跃”也需要区分。',
'写局部插入和删除函数。测空表插入、删唯一结点、连续删首尾；每次同时核对正向与反向。')
add('双向遍历、查找与标准库','把数据结构能力和工具接口分开。',
'''<p class="lead">多一条回头路，不等于一跳就到第 k 位。</p><p>双链正向遍历从 nxt[H] 出发，遇 T 停；反向从 pre[T] 出发，遇 H 停。查找值时沿某个方向逐个比，最坏 O(n)。找第 k 位仍要计步；可以选择从较近的一端开始，但最坏仍是线性。</p><p>C++ 的 <code>std::list</code> 提供双向迭代器。你可以把迭代器暂时理解为“工具交给你的结点位置”；它不是数字下标，没有 <code>it+5</code> 或 <code>a[5]</code> 这样的随机跳转。</p>'''+table(['接口动作','阅读时要问'],[['insert(it,x)','把 x 插在 it 之前；it 是否有效？'],['erase(it)','删除 it 指向的元素，返回后继迭代器'],['begin() / end()','end 是尾后位置，不能解引用或删除'],['find(begin,end,x)','按值查找仍要逐个比较']])+'''<p>插入单个元素、删除单个已定位元素具有常数复杂度；删除使被删元素的迭代器与引用失效，不能再对原 it 做 ++。其他元素的迭代器不会仅因这次插入或删除失效。核对依据：<a href="https://eel.is/c++draft/list.modifiers" target="_blank" rel="noopener">C++ 工作草案 · list 修改操作</a>。</p><p>选用工具前，先手写一张局部箭头图。标准库让实现省力，不会替你证明题目中的删除策略正确。</p>''',
'有 1000 个结点时，list 迭代器能用 +500 直接跳到中间吗？|删除 it 后，为什么应接住 erase 返回的位置？|从 T 向左遍历时，把停止条件写成遇 T 会怎样？',
'分别给正向与反向遍历画起点和终点。','工具中的 end 类似尾后边界，只能比较位置，不能当数据结点读。',
'写出双链两种方向的值序列，验证互为逆序；再独立查阅并试用 list 完成同一组局部操作。','第 10～12 站；结构体、基本指针概念')
add('循环链表：终点变成回到起点','创建圆环，并避免零次访问与无穷访问。',
'''<p class="lead">围成一圈以后，不能再等“走到空”才停。</p><p>不带哨兵的循环单链表，最后一个结点的 next 指回第一个。空表可用 head=nullptr；只有 A 一个结点时，A 的 next 就指向 A 自己。先判空，再访问起点，随后沿链接走；走回起点意味着一圈完成。</p>'''+chain('入口 → A → B → C\n       ↑       ↓\n       └───────┘')+'''<p>若 cur=head 后立刻判断 cur!=head，第一次就失败，一位也访问不到。若一直判断 cur!=nullptr，非空正确圆环永远不会遇到空。循环的停止条件来自结构，不是背熟的格式。</p><p>创建时可先尾插建普通单链，非空时让尾巴连回头部；逐步创建圆环则每加入新人都要维持闭环。另一种表示是带哨兵的循环双链：空环 pre[H]=nxt[H]=H，真实结点围绕 H 连接；遍历从 nxt[H] 开始，遇 H 停。不同表示都可以，但边界规则要全程一致。</p>''',
'单结点圆环从 A 出发，几次访问算一整圈？|为什么 cur=head 后直接用 while(cur!=head) 会漏掉全部？|空环和单结点环，入口与链接有哪些差别？',
'先画 0 个、1 个、2 个结点，分别安排第一次访问。','不带哨兵的非空环要先访问一次，再检查是否回到起点；空表需另判。',
'分别创建空环、单结点环、三结点环；遍历一次并查找一个不存在的值，说明失败查找在哪里停止。')
add('围圈增删与报数：下一轮从谁开始','把圆环更新、计数规则与结束条件结合。',
'''<p class="lead">有人离开以后，报数棒要交给还在圈里的人。</p><p>不带哨兵的单向圆环在 p 后插入 u，仍是把 p 的旧后继交给 u，再把 p 接到 u。删除时要持有目标的前驱；如果删除 head，要把入口移给活跃后继。删掉唯一结点则变成空表，不能保留指向已删除结点的 head。</p><p>约定报数任务：n 人编号 1～n，第一轮从 1 报 1；每次第 k 个出列，下一位重新报 1。游标指向本轮报 1 的人，因此先走 k−1 步才到出列者。终止目标若是剩下 1 人，就在活跃数量为 1 时停。</p><div class="lab" id="circle-lab"></div>'''+'''<p>每轮真的走 k−1 步，总成本可能为 O(nk)；先把步数对当前人数取模能减少绕圈，但仍不能普遍保证 O(n)。只求最后存活者时有递推思路，但它不直接给出完整出列顺序。链表擅长局部删除，不代表擅长巨大的排名跳转。</p>''',
'当前人已经报 1，要删报 3 的人，先走几条边？|被删的是入口时，下一轮入口或游标应该落在哪位活人？|n=1 与 k=1 各能帮你检查哪条规则？',
'把报数写在人下面，不要把“走一步”和“报一个数”混在一起。','删前保存后继；删后从这个后继重新计数，独人情形单独结束。',
'手推 n=5、k=3，再与实验逐轮比较；自己实现后测 n=1、k=1、k 大于人数。要求说明完整出列与仅求存活者的区别。')
add('五级营地：会操作，也会说清代价','完成三类链表的基本操作闭环。',
'''<p class="lead">“插入 O(1)”要带上它的前提。</p>'''+table(['操作','已经知道所需位置','还要定位时'],[['单链在 p 后插入','O(1)','按值找 p 通常 O(n)'],['单链删除 u','知道前驱才是 O(1)','只知道 u 通常要找前驱 O(n)'],['双链删除 u','活跃编号 / 有效指针已知，O(1)','按值找 u 通常 O(n)'],['访问第 k 个','没有随机访问捷径','O(n) 最坏'],['遍历 / 查找','完整遍历或失败查找 O(n)','圆环必须有绕一圈的结束条件']])+'''<p>数组模拟使用固定槽位，节点容量要按累计分配计；指针版每结点增加链接与分配管理开销。连续数组有随机访问、较好的缓存局部性；链表并非整体上“更省空间、更快”。根据操作选工具。</p><h3>五级基础覆盖清单</h3>'''+table(['类型','创建','插入 / 删除','遍历 / 查找'],[['单链','第 4、6 站','第 7～9 站','第 5 站'],['双链','第 11 站','第 12 站','第 13 站'],['循环链','第 14 站','第 15 站','第 14～15 站']])+'''<p>验收时抽一类链，让孩子从空结构建起、修改首尾和中间、输出与查找。三类都能解释以后，再进入下一营地。第 10 站用于把箭头图翻译成五级常见的结构体与指针代码。</p>''',
'题目只给“第 k 个位置”，为什么不能直接宣称插入是 O(1)？|循环链查找不存在的值，怎样确认已找遍？|要每天随机读很多下标，数组与链表谁更直接？',
'把每次操作拆成“找到位置”和“修改关系”两笔账。','表示能力有取舍；判断效率必须包含全部动作。',
'遮住前文，选一类链完成五项基本操作。测关键反例、最小规模与边界；再换另一类说明规则变化。做不到的站保持“需要回访”。')
add('反转一条链：分开过去、现在和将来','用循环不变式保护尚未处理的后缀。',
'''<p class="lead">把箭头转身之前，先记住接下来去哪儿。</p><p>现在回到不带哨兵的单链、空编号 0。任务：保持每个结点身份与数据不变，把整条链逆序。把状态分成“已经反转的前段”和“尚未处理的后段”：prev 指向前段的入口，cur 指向后段的入口。</p>'''+chain('已反转：2 → 1 → 0     待处理：3 → 4 → 0')+'''<p>一轮只把 cur 从右边移到左边。改 cur 的后继之前，必须保存原 nxt[cur]，否则再也找不到剩下的后段。初始已处理段为空；循环结束时后段为空，整个反转结果由 prev 带头。</p>'''+code('prev = 0; cur = head;\nwhile (cur != 0) {\n    saved = ______;     // 下一轮的入口\n    // 让当前结点接到已反转段前面\n    // 更新两段的入口\n}\n// 新 head 应该指向哪一段？')+'''<p>每轮少一个待处理结点，时间 O(n)，额外变量 O(1)。空链与单结点无需另发明算法，应能自然走通。若保留旧 tail，反转后也要更新。用递归实现时还要计算调用栈空间，不能因为只写了一个函数就说空间 O(1)。</p>''',
'若先把 nxt[cur] 指向 prev，原来的后段入口还从哪里取得？|每轮结束时，prev 和 cur 各领着哪一段？|cur 变为 0 后，新的入口是谁？',
'拿三张卡片，纸上同时保留两条链，不要只看一条箭头。','先保存未来，再改变现在的链接；最后移动两个入口。',
'独立实现迭代反转。测空链、单结点、三结点；反转两次应恢复编号序列，用这条性质自测。','第 1～10、16 站；循环不变式')
add('快慢指针：同一路上的两种速度','从同步轮次理解中点与环。',
'''<p class="lead">一个走一步，一个走两步，要比较同一轮的状态。</p><p>对不带哨兵的普通单链，slow 与 fast 都从 head 出发。每轮 slow 前进一步、fast 前进两步；进入循环前必须确认 fast 及其下一位都存在，才能读第二条链接。空链也要安全退出。</p><p>找中点时先约定偶数长度选前中点还是后中点。按上述起点与“双步可走就继续”的写法，长度 4 会落到后中点。若归并排序切两半需要前中点，就要调整快指针初值或停止条件，否则长度 2 可能分不出更小子问题。</p><h3>如果链意外形成了环</h3><p>先画一个有 5 个结点的圈，编号 0～4，4 的下一位回到 0。假设某一轮开始 slow 在 0、fast 在 2。每轮 slow 走一步、fast 走两步，接下来两者的位置依次是 (1,4)、(2,1)、(3,3)。第三轮就追上了。</p><p>原因是 fast 每轮比 slow 多走一步。两者都进环后，从 slow 沿箭头数到 fast 的间隔，每轮增加 1；满一圈就重新从 0 算。环有 c 个结点时，这个间隔只可能是 0～c−1，继续至多 c 轮就会走到间隔 0，也就是相遇。“按模 c 变化”说的正是这种绕一圈重新计数。</p><p>检查相遇要先移动，再比较。一开始两者都在 head，只是我们把它们放在同一个起点，不能据此说有环。若没有环，fast 会先走到链尾或空位置，按前面的边界检查停下。</p>'''+coach('环入口推导：设入口前长度 a，从入口到相遇点距离 b，环长 c。相遇时快指针路程是慢指针的两倍，多出的路程为若干整圈，因此 a+b 是 c 的倍数（慢指针可能已多绕圈）。把一根放回 head，两根都每轮走一步，会在入口首次重合。此推导是选学，不要求五级阶段背公式。'),
'fast 还活着，为什么仍可能不能连续走两步？|长度 2 和 4 时，你的中点规则落在哪一位？|两根指针起步就相等，能据此判断有环吗？',
'把每轮开始、移动之后分两列，先不要写复杂条件。','每读一次下一位都要有存在依据；环检测比较的是移动后的状态。',
'分别测 0、1、2、5 个无环结点与一个带前缀的小环。选学者再自己推导入口定位，不直接背模板。','第 5、10、17 站；模运算（环入口选学）')
add('有序链合并：接到递归与分治','维护已输出部分与两条未处理链。',
'''<p class="lead">每次只比较两个队首，前提是两边各自有序。</p><p>两条不共享结点的升序单链分别为 [1,4,7] 和 [2,4,6]。保留两个当前入口，选择较小值的结点接到结果尾部，再沿它原来的后继前进。两值相等时固定先取左链，能保持相等元素来自两条原段的稳定顺序。</p><p>不变式：结果链已按序排列；所有尚未处理的结点仍能从两根入口找到；结果尾巴指向已接入部分的最后一位。某条链空了以后，另一条剩余部分可以整体接上。真实搬的是链接，不必新复制数据结点。</p><p>合并两链共访问至多 n+m 个结点，O(n+m) 时间；迭代局部链接可用 O(1) 额外空间。链表归并排序先分半、切断中间链接，递归分别排序，再合并。切断很关键：只记住中点，不会让左链自动变短。</p>'''+box('与递归课件相接','递归边界至少要处理空链与单结点；两结点必须真正分成 1+1。链表归并排序可做到 O(n log n) 时间；递归栈通常为 O(log n)，还需算清合并过程是否递归。')+'''<p>重新连链时，不允许结果尾部留下无意的回路。两个输入若共享结点，本节前提失效，应先处理共享关系，不能照搬合并。</p>''',
'取走左链队首后，下一次应该比较谁？|两边相等时固定先取左侧，为什么有助于稳定性？|只找到中点但不切断，递归收到的左链真的变短了吗？',
'先给每个相等值标上来源 L 或 R，再看相对次序。','分别检查“输出有序”和“未处理入口还在”；切半要实际改变终止链接。',
'先实现合并并测一侧为空、重复值、长短悬殊；再选学归并排序，重点检查长度 2 的递归下降。','第 17～18 站；有序合并、递归与分治')
add('按值操作：定位表 + 双链表','把值域很大与结点编号分离。',
'''<p class="lead">操作只给名字时，先用目录找到那张卡。</p><p>教学模型：当前序列中的值互不相同。每条指令要求“在值 x 后插入新值 y”或“删除值 x”。值可能大到 10⁹，不能直接为每个可能的值开一个槽位；也不能每次从头查找。</p><p>使用紧凑编号存双链，再用“值→活跃编号”的映射定位。插入时分配新编号、记录新值并更新映射；删除时移除对应映射。一个值删除后可以再次出现，但可以分配一个新编号，不必复用旧槽。</p>'''+table(['工作','典型成本'],[['map 定位值','每次 O(log M)，M 为当前规模'],['已定位后双链修改','每次 O(1)'],['处理 n 个初值、q 次操作','用 map 时 O((n+q) log(n+q))'],['最后沿链输出','O(最终长度)']])+'''<p>unordered_map 常提供平均常数级操作，但不能把它写成无条件最坏 O(1)。若所有操作可提前读入，也可收集所有出现过的值做坐标压缩；压缩只解决定位，不负责维护动态的队伍排名。</p><p>迁移原题：<a href="https://atcoder.jp/contests/abc344/tasks/abc344_e?lang=en" target="_blank" rel="noopener">AtCoder ABC344 E · Insert or Erase</a>。当前值互异与操作对象存在是题目保证；若去掉这些条件，要重新设计身份与合法性规则。</p>''',
'两个结点可以同值时，一个 value→id 映射还够用吗？|删除 x 后重新插入 x，旧映射为什么不能继续留着？|只压缩数值大小，能表示“刚插在 x 后面”这种顺序吗？',
'给两份表分工：一份回答“是哪张”，一份回答“挨着谁”。','映射负责身份定位，pre/nxt 负责当前邻接；两份状态在操作后都要一致。',
'手推 [8,2,5]：删 2、在 8 后插 9、在 5 后插 2。分别记录映射与链，再独立实现原题。','第 11～16 站；map 或坐标压缩')
add('最近还活着的邻居：删除就是跨接','把反复扫描变成局部邻接维护。',
'''<p class="lead">消失的位置不用一遍遍重新路过。</p><p>位置 1～n 固定在直线上，起初全都活跃。每次删掉一个仍活跃的位置 x，并报告删除前它最近的活跃左邻居和右邻居，不存在用边界表示。若每次向两边扫描 deleted 数组，连续空洞会被反复扫过。</p><p>按原位置顺序建双链，pre[x] 与 nxt[x] 就是当前最近活跃邻居。删 x 时让它的左右邻居互接：保持的是剩余元素原有相对顺序。哨兵可用 H=0、T=n+1；此处真实编号 1～n，与第 11 站的分配编号约定不同，必须在变量表中重新声明。</p>'''+chain('1 → 2 → 3 → 4 → 5\n删 2，再删 4：1 → 3 → 5')+'''<p>对 [1,3,5] 再删 3，它的最近活跃邻居是 1 与 5，不是原始相邻编号 2 与 4。初始化 O(n)，q 次已知活跃编号的删除 O(q)，输出另算，总 O(n+q)。若允许重复删除，alive 标记要先拦住它；否则旧邻居信息可能破坏新链。</p>''',
'删 2 和 4 后，再删 3，它的两侧现在是谁？|为什么 x−1 与 x+1 不再代表当前邻居？|若 x 已经被删过，pre[x] 还能作为有效活跃关系直接使用吗？',
'只把活跃位置写在纸上，删除时不要重排它们的编号。','双链维护“剩余者中的相邻”，不是最初数组中的相邻。',
'用长度 6 手推连续删中间、连续删边缘，再用朴素扫描版对拍双链版。明确缺少左邻与右邻的输出约定。','第 11～16 站；稳定编号、复杂度估算')
add('离线倒着想：把删除改成恢复','明确已知未来、逆序状态与回答时刻。',
'''<p class="lead">正着看越来越碎，倒着看可以一块块接回来。</p><p>综合教学模型：n 个位置初始都活跃。操作 D x 删除尚活跃的位置，操作 Q 询问“最长连续活跃段”的长度。若只维护双链，能快速找到邻居，却不会自动知道全局最长段是多少。</p><p>若全部操作事先给出，可以离线处理：先标记最终仍活跃的位置，建立它们的连续段。然后从最后一条操作往前看。正向删除在倒序里变成激活一个位置；只需检查它原位置的 x−1、x+1 是否活跃，若是则合并对应连通块。</p><p>并查集维护每个活跃连通块大小，合并时更新最大值。每次 Q 记录当前最大值，全部结束后把记录的回答顺序倒回来。注意这里是<strong>原位置连续</strong>：不能因为双链里 1 与 3 相邻就把它们当作没有缺口的一段。</p>'''+coach('时间线核对：逆序处理第 i 条操作之前，结构应对应正向做完第 i 条后的状态。遇 Q 不修改结构，直接回答；遇 D x 就激活 x，使结构回到做这次删除之前。初始化 O(n)，使用按秩/大小合并与路径压缩的并查集，总 O((n+q)α(n))。若允许重复删除，需要次数或有效操作记录，不能每见一条 D 都激活。')+'''<p>离线的条件是可以读取全部操作且不要求立即向交互系统回答；它是改变处理顺序的方法。下一站再看能随时退回上一步的在线撤销。</p>''',
'为什么只知道当前左右活跃邻居，还不足以知道最长连续段？|倒序遇到 D x 时，结构应从哪一个时刻回到哪一个时刻？|位置 2 不活跃时，1 与 3 在链上相邻，能合并成连续段吗？',
'画一条时间轴，在每次删除前后分别写出活跃集合。','物理位置连续与活跃队伍相邻是两种关系；合并要检查原编号相邻。',
'手推 n=5：Q、D 3、Q、D 2、Q。正向扫数组写答案，再倒序激活比对；还没学并查集时先做纸面。','第 21 站；离线思想、并查集（不会时先纸面选学）')
add('删除可以撤销：先记下改变了什么','用栈保证恢复时的环境正确。',
'''<p class="lead">撤销最后一步，先让世界回到它发生前的样子。</p><p>双链允许两种操作：删除一个活跃结点；撤销最近一次尚未撤销的删除。删 u 前记录 (u,p,q)，p 与 q 是那一刻的邻居，再跨接 p 与 q。把这条记录放到栈里。</p><p>撤销时取栈顶，把 u 放回 p 与 q 之间。为什么可以相信这两位邻居还适合接回？因为后发生的删除已经先撤销，环境沿时间倒退回来了。前提是期间只有这种受控删除及其逆序恢复，没有任意插入、移动或清空。</p><div class="lab" id="undo-lab"></div>'''+coach('核对例：H↔A↔B↔C↔T，先删 B 再删 A。若先恢复 B，它记录的左邻 A 仍不活跃，会断开正确入口；先恢复 A，再恢复 B，才与原状态一致。空间记录每个未撤销动作 O(1)，q 次操作共 O(q)。不要释放还要恢复的结点；数组槽位也不能提前复用。')+'''<p>这是搜索回溯中“试一种选择→探索→撤销”的基本功。可以把记录扩展成“改了哪个字段、原值是多少”的修改栈，从而逆序恢复多个字段。它仍不是任意历史版本的数据结构。</p>''',
'先删 B 再删 A，若先恢复 B，记录中的左邻还活着吗？|为什么后做的删除要先撤销？|要恢复的结点槽位被新结点占用了，旧记录还可靠吗？',
'在每次删除旁边记当时左右邻居，不要事后猜。','撤销不仅恢复一个结点，也要求邻居状态与当时吻合；栈保证逆序。',
'实现只含删除与撤销的局部模块，测空栈撤销、删到空、连续撤销。先用快照数组当裁判，再检查栈版。','第 12、21 站；栈、回溯的“做与撤销”')
add('一串链变成图：链式前向星','用同一套链接思想组织多条邻接表。',
'''<p class="lead">每个城市各有一个入口，串起它发出的道路。</p><p>图里一个点可以连向多个点。给每个顶点 u 一个 <code>head[u]</code>，记录它第一条出边的编号；给每条边 e 记录 <code>to[e]</code>、<code>nextEdge[e]</code>。这里链接串起来的是<strong>边记录</strong>，不是顶点队伍。</p><p>约定边编号从 1 开始，0 表示没有边。加入 u→v 时，把新边头插到 u 的边链：新边终点为 v，后继为旧 head[u]，再更新 head[u]。因此同一顶点的遍历顺序通常与加入顺序相反。</p>'''+table(['变量','角色'],[['u','当前顶点编号'],['e','当前边编号'],['to[e]','这条边的终点顶点'],['nextEdge[e]','同一出发点的下一条边'],['head[u]','顶点 u 的第一条出边']])+'''<p>遍历从 e=head[u] 开始，沿 nextEdge 直到 0。不能写成 e=to[e]，那会把顶点编号误当边编号。无向边通常存两条有向边，因此容量至少按 2m 条边计算；全部邻接表遍历 O(n+m)，不是每个点都扫描所有 m 条边。</p><p>链表思想帮你理解图的存储。图搜索中的“访问过”标记与链中结点活跃状态不是同一职责，应另设变量。</p>''',
'顶点 2 的第一条边恰好编号 7，遍历游标应该从 2 还是 7 开始？|to[7]=4 表示下一条边是 4 吗？|无向道路数 m，为什么可能需要 2m 个边槽位？',
'把边画成带编号的票，每张票写“终点”和“下一张票”。','head 领的是边记录链；to 才把你带到图中的另一个顶点。',
'画 4 点 3 边小图，手写 head/to/nextEdge 表，再输出每点邻居；加入孤立点、重边与无向双向存储测试。','第 4～7 站；图的顶点与边概念')
add('堆 + 链表：最近邻候选会过期','区分局部邻接维护与全局最优选择。',
'''<p class="lead">堆里那张旧通知，说的邻居可能已经变了。</p><p>教学模型：有序位置 x₁&lt;…&lt;xₙ。每步选当前相邻且距离最小的一对，把二者都删除；距离相同选左位置更小的一对；直到不足两点。双链告诉你谁相邻，小根堆负责从候选中选最小距离。</p><p>初始化把 n−1 对相邻者入堆。弹出 (距离,u,v) 后先验证：u、v 都活跃，且 nxt[u]=v；否则这条候选已过期，丢弃继续弹。删掉一对后，只可能新增“原左邻 L 与原右邻 R”这一对，把它入堆（两者必须都是真实活跃结点）。</p>'''+chain('L ⇄ u ⇄ v ⇄ R  →  L ⇄ R')+'''<p>别把“曾经相邻”当作“现在仍相邻”。本模型位置不变、结点不恢复，因此活跃与相邻检查足够；若权值会变化或编号会复用，还要比较版本号或当前代价。</p><p>初始化 O(n) 对候选，每次有效删除最多新增一对，总入堆 O(n)，每条最多弹出一次，总 O(n log n)、空间 O(n)。若题意改成“选若干对使总收益最大”，按当前最小距离选择是否正确要另证明。本模型的顺序是题目规定，不能偷换成未经证明的贪心结论。</p>''',
'在 [0,2,3,10] 中先删 2、3 后，堆里的 (0,2) 还能用吗？|删除中间一对后，哪一对是新出现的相邻候选？|为什么不能把“规则要求取最小”直接当作“这样使总和最优”的证明？',
'同时维护“真实活跃链”和“旧候选通知堆”，不要把堆视为当前完整真相。','弹出后验证，再执行；过期记录可以留在堆里，但不能产生动作。',
'用每轮扫描所有活跃相邻对的慢程序做裁判；小规模随机坐标对拍堆版，覆盖同距离与仅剩 1 人。','第 21 站；优先队列、比较规则、懒删除')
add('按值删点，按位置计贡献','从最近边界推导子数组最值贡献。',
'''<p class="lead">操作顺序按值排，链上的顺序仍按位置排。</p><p>综合模型：数组中各值互异，求所有非空连续子数组的最小值之和。直接枚举每个子数组很慢；换成问“aᵢ 会作为多少个子数组的最小值”。左右第一个比它小的位置记为 L、R，没有则取 0、n+1。</p><p>用从 1 开始的位置编号。若 aᵢ 是某段最小值，左端必须在 L+1～i，右端必须在 i～R−1。两边可独立选择，所以贡献为 aᵢ·(i−L)·(R−i)。先自己画出可选端点，再用公式，不能凭记忆直接套。</p><p>怎样用链表找到这些边界？先按原位置建双链，再按数值从大到小依次删点。处理 i 时，较大的值已删除；其余活跃值都比 aᵢ 小，所以链上的最近邻居恰是所需 L、R。先记贡献，再删 i。</p>'''+coach('互异例 [3,1,2]：处理 3 的位置 1，边界 0、2；处理 2 的位置 3，边界 2、4；最后处理 1 的位置 2，边界 0、4。贡献分别为 3、2、4，总和 9。排序 O(n log n)，链操作总 O(n)，空间 O(n)。乘法从第一步就转 long long，并依据 n 与值域检查 64 位是否足够。')+'''<h3>重复值是一个新的分配问题</h3><p>[2,2] 的长度 2 子段不能被两位都认领。可给 (值,原位置) 定义唯一顺序，让相等时左侧位置优先作为最小值，再按这个关键字降序删除。此时边界语义变成左侧 ≤、右侧 &lt;；左右不能同时取严格或同时取非严格。单调栈也能求这些边界且做到线性，但要重新证明弹栈条件。</p>''',
'若 i 的左端越过 L，为什么 aᵢ 就不再是唯一最小值？|要让活跃邻居都更小，应该先删大值还是先删小值？|[2,2] 的整段应交给谁，怎样避免计两次？',
'先把左端与右端列成两列，用格子数可组合的端点对。','贡献计算的关键不是公式，而是每段恰好被一个位置认领；重复值需固定归属。',
'先对互异数组逐段枚举，与按值删点的贡献逐项核对；稳定后才加重复值。测试 [3,1,2]、[2,2]、递增与递减数组。','第 21 站；排序、贡献法、乘法计数、64 位整数')
add('只删不恢复：后继并查集选学','从跨接推广到跳过一整片已删除位置。',
'''<p class="lead">有时只需要知道右边下一位，不需要整条双链。</p><p>教学任务：位置 1～n 起初都活跃，每次查询从 x 开始（包含 x）第一个仍活跃的位置；删除指定活跃位置。保留 n+1 作“没有”的哨兵。定义 find(x) 返回从 x 起的第一个活跃位置。</p><p>开始每个位置指向自身。删除 x 后，把它的代表指向 find(x+1)；沿代表查找时做路径压缩，让经过的旧位置直接记住更远的活跃后继。哨兵始终指向自己，不可删除。</p><p>这个定向跳转结构的根必须有“右边第一个活跃位置”的语义，不能随手按树大小决定谁当根。它与一般双链也不同：被跳过的位置默认不会重新活跃。路径压缩覆盖了中间信息，不能直接用于上一站那种任意恢复。</p>'''+coach('复杂度不要滥用 α(n)：仅有定向链接加路径压缩时，不直接套用“路径压缩 + 按秩合并”的标准结论。若要使用标准近常数摊还界，可以另设计普通并查集，把连续删除区间按大小合并，并给根维护右端点；查询删除位置时返回该块右端点+1。这个版本需要额外的活跃/删除标记和区间语义证明。')+'''<p>理解它的价值在于识别“操作单向发生、已删区间可以跳过”。还没学并查集时，把本节标为未来回访即可，双链主线已经能解决已知结点删除的问题。</p>''',
'删掉 2、3、4 后，find(2) 应指向谁？|若路径已把 2 直接指到 5，重新激活 3 会让哪条旧捷径失效？|为什么不能随意交换根，破坏“向右第一个”的含义？',
'把每条跳转写成一句承诺：“从这里起，下一位至少到那里找”。','这种信息压缩利用了删除不会反悔；恢复操作需要别的设计。',
'用 n=6 比较逐格扫描、双链、后继跳转的回答；记录各自支持什么操作，不要求本次写出并查集完整代码。','第 21～23 站；并查集、路径压缩（选学）')
add('第 k 位与区间操作：链表的能力边界','知道何时改用树状数组、平衡树或其他结构。',
'''<p class="lead">认识工具的边界，也是提高组能力。</p><p>如果反复要求“删除当前第 k 位”，链表的局部删除虽快，定位仍可能每次走 O(n)。当 n、q 都达 2×10⁵ 时，总 O(nq) 无法因使用链表而消失。先看查询到底给编号、值，还是动态排名。</p><p>若位置来自固定原数组，只做删除，可用树状数组存每个位置是否活跃（1/0）。前缀和就是前缀活人数，第 k 位是最小的、前缀和≥k 的原位置。更新删除 O(log n)；外层二分位置并每次求前缀和为 O(log² n)，树状数组倍增定位可降为 O(log n)。</p><p>若允许在任意新位置插入、整段翻转和按排名切分，普通链表与固定下标树状数组都未必够用，可以以后学习带子树大小的隐式平衡树。不要现在就背它的整份模板。</p>'''+table(['需求','先考虑的能力'],[['已知活跃编号，局部插删','双链 / 数组模拟'],['固定位置删点，动态第 k 个','树状数组或线段树计数'],['整段翻转，按排名分裂合并','隐式平衡树等进阶结构'],['稀疏图的出边枚举','邻接表 / 链式前向星'],['静态数组按下标读取','连续数组']])+'''<p>剪下已知端点的一段并接到已知位置，外部边界改接可为 O(1)，但找端点、检验目的位置不在段内、逐点反转内部链接都另计成本。不要把“剪接一段”与“把一段顺序翻转”混为一谈。</p>''',
'指令给“结点 7”与“第 7 个结点”，定位成本为什么可能不同？|固定位置只删点，哪种信息能把排名变成前缀查询？|反转一段时只交换两端的外部链接，内部箭头会自己转向吗？',
'先画指令已知的信息与仍要查出的信息。','很多所谓慢在插删，实际上慢在按排名定位；把成本拆开。',
'给五种需求各选一项结构并说明前提。选学者把约瑟夫的定位换成活人数第 k 查询，与第 15 站小样例对拍。','第 16、21 站；前缀和；树状数组仅作提高衔接')
add('独立任务板：从会改箭头到综合建模','通过有完整约定的小题证明迁移能力。',
'''<p class="lead">这次先读题、画图，再自己选择工具。</p><p>以下三题为原创训练任务，按顺序任选当前合适的一题。题面不藏边界约定；先独立手推，折叠提示只在卡住后打开。这里不提供完整解题代码。</p>
<article class="mission"><span class="tag">任务 A / 五级基础巩固</span><h3>卡片队伍</h3><p>初始为空。第一行 Q（1≤Q≤1000），随后 Q 行指令：<code>I p id v</code> 在活跃编号 p 后插入新编号 id、数值 v，p=0 表示插在最前面；<code>D id</code> 删除活跃 id；<code>F v</code> 输出当前第一个值为 v 的结点编号，找不到输出 0。真实 id 在 1～Q 内且从不重复分配，非零 p 和 D 的对象保证活跃，|v|≤10⁹。所有操作结束后另输出一行从头到尾的值，空表输出 EMPTY。允许相同值。</p><p>手推输入：Q=6；I 0 1 7；I 1 2 7；F 7；D 1；F 7；D 2。自己写出三行输出，再实现。规模小，找前驱的线性代价可以接受。</p><details><summary>提示阶梯 · 先身份，再前驱</summary><p>第一层：两个值 7 不是同一张卡，用 id 区分。</p><details><summary>第二层：把删除交给前驱</summary><p>若选单链，从入口哨兵找指向 id 的那个结点，再绕过目标；不要把值为 7 的所有结点删掉。</p></details></details></article>
<article class="mission"><span class="tag">任务 B / CSP 综合基础</span><h3>可撤销的队伍</h3><p>第一行 n、q（1≤n,q≤2×10⁵），初始队伍为 1～n。随后 q 行：<code>D x</code> 删除保证活跃的 x，并记录这次动作；<code>U</code> 撤销最近一次未撤销的删除，记录栈为空则不操作；<code>N x</code> 查询保证活跃的 x 的当前左右邻居，不存在各输出 0。每次 N 输出一行两个数，最后输出一行活跃编号，空队伍输出 EMPTY。除此之外没有插入和移动。</p><p>手推：n=4，操作 D 2、D 1、U、N 3、U、N 2。记录栈和邻接关系要一起画。目标总时间 O(n+q)，空间 O(n+q)。</p><details><summary>提示阶梯 · 恢复依赖什么</summary><p>第一层：删除时就记录当时的左右邻居，别在恢复时重新猜。</p><details><summary>第二层：证明后进先出</summary><p>用先删 2、再删 1 说明任意恢复顺序会出错。每次 U 必须取栈顶记录。</p></details></details></article>
<article class="mission"><span class="tag">任务 C / 提高阶段综合</span><h3>相邻配对日志</h3><p>第一行 n（1≤n≤2×10⁵），第二行严格递增的 n 个整数位置 xᵢ（−10⁹≤xᵢ≤10⁹），原编号 1～n。反复删除当前相邻且距离最小的一对，距离相同时选左端原编号更小的一对。直到不足两点。输出 ⌊n/2⌋ 行，每行是被删对的原编号，左、右依次输出。n=1 时没有输出行。</p><p>先手推坐标 [0,2,3,10,11]，写每轮全部候选，再设计算法。目标 O(n log n)；距离与排序规则使用足够宽的整数类型。用全扫描慢程序验证小数据。</p><details><summary>提示阶梯 · 堆里的消息还有效吗</summary><p>第一层：分开“谁相邻”和“哪对最小”两项职责。</p><details><summary>第二层：弹出后先验证</summary><p>检查两端都活跃且仍相邻；删除后只有跨过被删对的两侧可能新增一对。</p></details></details></article>
<h3>外部迁移题</h3><p><a href="https://atcoder.jp/contests/abc237/tasks/abc237_d?lang=en" target="_blank" rel="noopener">ABC237 D · LR insertion</a>：按左右指令建立序列，试比较正向双链与倒序思考。<a href="https://atcoder.jp/contests/abc344/tasks/abc344_e?lang=en" target="_blank" rel="noopener">ABC344 E · Insert or Erase</a>：大值域中的动态插删。它们是训练题，不贴作 CSP 真题或等级认证。</p>''',
'你选的题，指令给的是编号、数值还是排名？|每个变量分别负责身份、邻接、候选还是历史？|你准备哪一个小反例，专门检验自己最不确定的步骤？',
'先从题面圈出对象的身份和合法操作，再决定用哪种链。','数据结构只是维护题意的工具；先说明每步应该发生什么，再写更新。',
'任选一题，提交自己的模型、变量表、代码与三类测试证据。通过后用自己的话复盘，隔天再换一个限制做迁移。','任务 A：第 16 站；B：第 23 站；C：第 25 站')
add('调试与方法卡：证明这条链真的完整','用可达性、不变式和对拍形成可靠习惯。',
'''<p class="lead">看起来像链，还要经得起双向检查与边界测试。</p><p>先分类：编译错误看语法与类型；卡住看循环是否推进、是否误造环；崩溃先查越界、空指针、释放后访问；结果不对则找手推与程序第一次分叉的位置。不要一出错就整份重写。</p>'''+table(['结构证据','能发现的问题'],[['线性链访问到终止位置；调试时记录 seen','自环、长环、错的结束标记'],['从入口可达的真实结点数 = size','漏接结点、孤立结点；size 本身也需可靠更新'],['双链每个有效相邻关系互相一致','只改了一个方向'],['正向序列 = 反向序列的逆序','首尾更新或逆向链接错误'],['映射只指向活跃且值相符的结点','值删掉后残留旧身份'],['每轮与朴素 vector 模型比较','复杂操作顺序错误']])+'''<p>对拍时用很小的 n 随机生成<strong>合法操作</strong>，简单 vector 版本用插入、删除与扫描作裁判，复杂度可以慢但逻辑要独立。每次操作后就比较完整编号序列，不能只比最后输出。失败时保存随机种子与操作前缀，再逐条删减到最小反例。</p><p>调试检查遍历整条链可能 O(n)，适合小样本验证；正式大数据运行时不要在每次操作后一直全链检查，把 O(1) 操作无意变成 O(n)。学习环境允许时，地址与未定义行为检测工具也能辅助发现内存问题。</p><h3>一张由你完成的方法卡</h3>'''+table(['提问','你的记录'],[['题目反复做什么动作？','在下方笔记填写'],['给我的是值、编号还是排名？','在下方笔记填写'],['入口、终止标记、活跃身份怎么约定？','在下方笔记填写'],['改之前必须保存哪些旧信息？','在下方笔记填写'],['操作后哪些不变式应恢复？','在下方笔记填写'],['定位、修改、输出分别花多少？','在下方笔记填写'],['哪三个测试最能打破我的假设？','在下方笔记填写']])+'''<p>正式反思等改对后由你自己写：错在哪里，为什么会错，下次怎么防。仍卡住就记“待复盘”，今天只保存卡片，隔天从题意重新画图。</p>''',
'出现环、漏接一段、重复删除，分别能用哪条检查最早发现？|你的快程序和慢裁判若用了同样的链接代码，还能独立互证吗？|今天学到的哪条检查动作能迁移到图、递归或其他数据结构？',
'先找第一次偏差，不先统计最后错了多少个数。','可达关系、身份与状态一致性是主线；测试要特意撞击你的前提。',
'选择一份自己写过的链表代码，做一次小规模对拍并缩减失败样例（若有）。只记录真实观察，不预填“已掌握”。','前面已完成的站点；随机测试可选学')
